/// Registers the active render device and clears old device residency once.
pub(crate) fn use_gpu_device(&self, device_identity: usize) {
    let changed = {
        let mut inner = self.lock();
        match inner.gpu_device {
            Some(previous) if previous != device_identity => {
                inner.gpu_device = Some(device_identity);
                inner.revision = inner.revision.saturating_add(1);
                true
            }
            None => {
                inner.gpu_device = Some(device_identity);
                false
            }
            Some(_) => false,
        }
    };
    if changed {
        self.gpu_mesh_cache.clear();
        self.gpu_texture_cache.clear();
    }
}
